  "paper": {
    "title": "EXP-Bench: Can AI Conduct AI Research Experiments?",
    "authors": [
      "Patrick Tser Jern Kon",
      "Jiachen Liu",
      "Xinyi Zhu",
      "Qiuyi Ding",
      "Jingjia Peng",
      "Jiarong Xing",
      "Yibo Huang",
