      "label": "Frame black-box LLM adaptation as text-only ranking/scoring problem",
      "support_level": null,
      "source_refs": [],
      "description": null,
      "fields": {
        "decision": {
          "choice": "Train a small auxiliary model as an energy-based scorer that distinguishes target-domain from source-domain text using only text inputs and outputs",
          "alternatives": [
            "Prompt engineering and in-context learning (no persistent adaptation)",
            "Fine-tuning via API (Azure-SFT) — opaque, expensive, privacy-risky",
            "Retrieval-augmented generation (kNN-Adapter) — still needs probabilities for interpolation"
          ],
          "rationale": null
        }
      },
      "evidence_notes": [
        "Residual EBM formulation (Deng et al., 2020) enables distribution shaping without accessing LLM internals; only text outputs needed"
