      "label": "Standard MLE or MCMC for EBM training",
      "support_level": null,
      "source_refs": [],
      "description": null,
      "fields": {
        "dead_end": {
          "hypothesis": "Direct MLE or MCMC sampling could estimate Z_theta(x) sufficiently",
          "failure_mode": "Computationally intensive and imprecise; MCMC for discrete text is especially problematic",
          "lesson": "Noise Contrastive Estimation (NCE) avoids Z_theta entirely by converting density estimation to classification",
          "why_failed": null
        }
      },
      "evidence_notes": [],
      "pos": {
        "x": 215.0,
        "y": 470.0
