    {
      "id": "N07",
      "kind": "decision",
      "label": "Use ranking-based NCE loss to bypass intractable partition function",
      "support_level": null,
      "source_refs": [],
      "description": null,
      "fields": {
        "decision": {
          "choice": "Minimize KL between parameterized posterior pθ(k|{xk}) and data-to-noise ratio q(k|{xk}); extends binary NCE to ranking over multiple samples",
          "alternatives": [
            "Standard binary NCE (Gutmann & Hyvarinen 2010) — only real vs. noise, no ranking",
            "MLM loss — mask words in ground-truth, train on masked word prediction",
            "Contrastive learning with fixed negatives"
          ],
          "rationale": null
        }
      },
      "evidence_notes": [
        "Ma & Collins (2018) ranking NCE; optimal solution recovers p_theta(x) = p_data(x)"
      ],
      "pos": {
