      "support_level": null,
      "source_refs": [],
      "description": null,
      "fields": {
        "decision": {
          "choice": "Learn a latent z from (state, reward) samples that compresses the reward function using a permutation-invariant encoder + information bottleneck",
          "alternatives": [
            "SF/FB: linearized value functions over pre-specified features",
            "Goal-conditioned RL: restrict to goal-reaching reward family",
            "Meta-RL: require compartmentalized per-task datasets (not available)"
          ],
          "rationale": null
        }
      },
      "evidence_notes": [
