      "fields": {
        "dead_end": {
          "hypothesis": "A standard fine-tune on OpenWebText would, eventually, un-permute the embedding rows since each row gets direct gradient from its token.\n",
          "failure_mode": "Per batch, only ~16% of vocabulary rows are touched (one row per unique token in the batch), so embedding updates are sparse and slow. Meanwhile the transformer receives gradients against permuted inputs on every step and rapidly adapts to that noise, so by the time the embedding would converge, the rest of the model has drifted.\n",
          "lesson": "The embedding matrix cannot be fixed by end-to-end training alone. A structural intervention is needed that either (a) freezes the transformer while the embedding path recovers, or (b) bypasses the permuted embedding entirely using an alternative content source (the small model).\n",
          "why_failed": null
        }
      },
      "evidence_notes": [],
      "pos": {
        "x": 90.0,
        "y": 250.0
      }
