    {
      "id": "N04",
      "kind": "decision",
      "label": "Replace permuted wte with small model embedding + linear adapter (freeze-then-unfreeze)",
      "support_level": null,
      "source_refs": [],
      "description": null,
      "provenance": "official-solution",
      "fields": {
        "decision": {
          "choice": "Discard the large model's permuted wte at init. Use the small model's uncorrupted embedding E_small (d_small-wide) as the new wte. Insert a bias-free linear adapter A: R^{d_small} -> R^{d_large} between the embedding output and the transformer. Freeze everything except A until alignment is established, then unfreeze all, then bake A into wte to restore the original architecture.\n",
          "alternatives": [
            "Direct vanilla fine-tune (N02): performed poorly",
            "Distill small model into large model directly: would fix logits but not the large model's own internal representation; slower convergence",
            "Permutation search / inverse π estimation: combinatorial over V=50304, infeasible in the run budget"
          ],
          "rationale": null
        }
